import QrCode from "@marko-ui/shadcn/ui/qr-code/qr-code.marko";
import Button from "@marko-ui/shadcn/ui/button/button.marko";

<div class="flex flex-col items-start gap-4">
  <QrCode/qrCodeApi value="https://example.com" size="lg">
    <@overlay>
      <div class="flex size-8 items-center justify-center rounded-sm bg-primary text-xs font-bold text-primary-foreground">
        UI
      </div>
    </@overlay>
  </QrCode>
  <Button type="button"
    size="sm"
    variant="outline"
    onClick() {
      qrCodeApi()
        .getDataUrl("image/png")
        .then((dataUrl: string) => {
          const anchor = document.createElement("a");
          anchor.href = dataUrl;
          anchor.download = "qr-code.png";
          anchor.click();
        });
    }
  >
    Download PNG
  </Button>
</div>
